    ('74b8f34e-0517-585c-a65f-d052336b4543'::uuid, 'Quiz — Aujourd’hui, autrefois, et ce à quoi on s’habitue', 'Anglais', '3e', 'Exprimer l’habitude', 'b78b19d0-a84a-57a9-96bf-eb61ed418a03'::uuid),
    ('3d52d6fc-5988-567a-95d8-cccac52ee0aa'::uuid, 'Quiz — To, in order to, so that', 'Anglais', '3e', 'Exprimer le but', '84e21116-e77f-5dc6-b7ba-396d56d78b15'::uuid),
    ('55746a39-87aa-58b5-9a76-d1f288edd2bc'::uuid, 'Quiz — For, since, ago, how long', 'Anglais', '3e', 'Exprimer la durée', '296c0e05-ae55-5ca8-8bb5-8c4654e6e42c'::uuid),
    ('e9ddb514-2edc-5d9d-bd25-23798d1e1f50'::uuid, 'Quiz — Rapporter les paroles de quelqu’un', 'Anglais', '3e', 'Le discours indirect', 'c49074fe-47ad-5937-b2cb-12986f5ca29a'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('1dd454ca-63f6-5623-bf6f-42b56f360451'::uuid, 'b9badb9d-38f6-5ba1-994d-1ef704071ab1'::uuid, 'Quel est le pluriel de « child » ?', 'mcq', '["children","childs","childes","childrens"]'::jsonb, 0, 'C’est l’un des pluriels irréguliers les plus fréquents.', 1),
    ('5f48a74a-424a-5117-a3c5-07a111a13fba'::uuid, 'b9badb9d-38f6-5ba1-994d-1ef704071ab1'::uuid, 'Quel est le pluriel de « city » ?', 'mcq', '["cities","citys","cityes","cityies"]'::jsonb, 0, 'Consonne + y donne -ies ; « boy » fait « boys » car le y suit une voyelle.', 2),
    ('80c0c744-45e1-585d-9a6b-a41972adef02'::uuid, 'b9badb9d-38f6-5ba1-994d-1ef704071ab1'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["I need some advice.","I need an advice.","I need some advices.","I need two advices."]'::jsonb, 0, '« Advice » est indénombrable : on dit « a piece of advice ».', 3),
    ('6bc86263-3a5b-5aa8-a743-dabb8e94de49'::uuid, 'b9badb9d-38f6-5ba1-994d-1ef704071ab1'::uuid, 'Comment compte-t-on un nom indénombrable ?', 'mcq', '["En employant un partitif, comme « a piece of »","En ajoutant -s","En le faisant précéder de « a »","C’est impossible"]'::jsonb, 0, 'A glass of water, a piece of furniture.', 4),
    ('c8bb553c-dc45-5072-aeb9-d850d73d3746'::uuid, 'b9badb9d-38f6-5ba1-994d-1ef704071ab1'::uuid, 'Quel verbe accompagne « the news » ?', 'mcq', '["is","are","were","have"]'::jsonb, 0, 'Malgré le -s final, « news » est indénombrable et singulier.', 5),
    ('c9f6a201-c489-5b7f-8ead-add844bf0764'::uuid, 'b9badb9d-38f6-5ba1-994d-1ef704071ab1'::uuid, 'Quel est le pluriel de « knife » ?', 'mcq', '["knives","knifes","knifs","knifves"]'::jsonb, 0, 'Les noms en -f ou -fe font souvent leur pluriel en -ves.', 6),
    ('fe7d1365-a44b-52e1-9e64-1cddbd70bc13'::uuid, 'b9badb9d-38f6-5ba1-994d-1ef704071ab1'::uuid, 'Comment exprime-t-on la possession avec un nom animé ?', 'mcq', '["Avec ’s : my sister’s phone","Avec « of » uniquement","En inversant les deux noms sans marque","Avec « to » devant le possesseur"]'::jsonb, 0, 'Au pluriel en -s, on met l’apostrophe seule : the students’ books.', 7),
    ('832bf761-bc3d-5f9d-af25-137a55d809d2'::uuid, 'b9badb9d-38f6-5ba1-994d-1ef704071ab1'::uuid, '« Furniture » peut se mettre au pluriel en anglais.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un indénombrable : on dit « two pieces of furniture ».', 8),
    ('b511f11c-f9c7-52f9-9736-91de6b9be6d2'::uuid, 'bb807cb8-d0a9-5fdc-a14e-157e7902977d'::uuid, 'Quand emploie-t-on « an » plutôt que « a » ?', 'mcq', '["Devant un son de voyelle","Devant la lettre A, E, I, O ou U","Devant un nom pluriel","Devant un nom propre"]'::jsonb, 0, '« An hour » (h muet) mais « a university » (son « you »).', 1),
    ('0012f41a-d54b-5da0-beb9-4d1b624f0bc5'::uuid, 'bb807cb8-d0a9-5fdc-a14e-157e7902977d'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["She is a dentist.","She is dentist.","She is the dentist by profession.","She is an dentist."]'::jsonb, 0, 'Le métier prend l’article indéfini en anglais.', 2),
    ('93d055ec-e2d8-56be-9c41-526857754312'::uuid, 'bb807cb8-d0a9-5fdc-a14e-157e7902977d'::uuid, 'Comment traduit-on « J’aime les chiens » ?', 'mcq', '["I like dogs.","I like the dogs.","I like a dogs.","I like some the dogs."]'::jsonb, 0, 'Un pluriel au sens général ne prend aucun article.', 3),
    ('ae7341ee-2e43-5fac-8fb1-ee53ad1e5b2e'::uuid, 'bb807cb8-d0a9-5fdc-a14e-157e7902977d'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["I play the piano and I play football.","I play piano and I play the football.","I play the piano and I play the football.","I play piano and I play football."]'::jsonb, 0, 'Instrument de musique avec « the », sport sans article.', 4),
    ('166d0044-96f8-5633-9311-3d7f8d0e04c4'::uuid, 'bb807cb8-d0a9-5fdc-a14e-157e7902977d'::uuid, 'Devant quel type de nom géographique emploie-t-on « the » ?', 'mcq', '["Les fleuves, océans et chaînes de montagnes","Les villes","Les pays au singulier","Les continents"]'::jsonb, 0, 'The Thames, the Atlantic, the Alps, the Netherlands.', 5),
    ('61545d17-35f9-537f-a1f2-289951976fe1'::uuid, 'bb807cb8-d0a9-5fdc-a14e-157e7902977d'::uuid, 'Comment traduit-on « deux fois par semaine » ?', 'mcq', '["twice a week","twice the week","twice week","two times the week"]'::jsonb, 0, 'L’article indéfini exprime la fréquence.', 6),
    ('b38340cb-3c43-578a-887c-acc07216cfc2'::uuid, 'bb807cb8-d0a9-5fdc-a14e-157e7902977d'::uuid, 'Quelle différence y a-t-il entre « go to school » et « go to the school » ?', 'mcq', '["Le premier désigne l’activité d’étudier, le second le bâtiment précis","Le premier est familier, le second soutenu","Les deux sont identiques","Le second est incorrect"]'::jsonb, 0, 'Même distinction pour « hospital » ou « church ».', 7),
    ('8a94411f-c759-5561-a2ad-bbe0c464c84c'::uuid, 'bb807cb8-d0a9-5fdc-a14e-157e7902977d'::uuid, 'C’est la première lettre du mot qui décide entre « a » et « an ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est le son : « an hour » commence par un h muet, « a university » par un son « you ».', 8),
    ('0108cc09-0485-5507-9c85-41d1d90ca33d'::uuid, 'eecddf51-ee04-5c1b-a456-be52697a7c10'::uuid, 'Quel démonstratif emploie-t-on pour un objet proche au pluriel ?', 'mcq', '["these","this","those","that"]'::jsonb, 0, '« These shoes are new. »', 1),
    ('97370796-170e-5161-b0e3-24f996b11e4f'::uuid, 'eecddf51-ee04-5c1b-a456-be52697a7c10'::uuid, 'Quel démonstratif emploie-t-on pour un objet éloigné au singulier ?', 'mcq', '["that","this","these","those"]'::jsonb, 0, '« That house over there is old. »', 2),
    ('09b10eb2-143f-5b6f-b685-fb4253e4b0ed'::uuid, 'eecddf51-ee04-5c1b-a456-be52697a7c10'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["These children are noisy.","This children are noisy.","Thoses children are noisy.","That children are noisy."]'::jsonb, 0, 'Le démonstratif s’accorde en nombre avec le nom.', 3),
    ('938d2a35-c288-5caa-84c8-ec88b3ad4e28'::uuid, 'eecddf51-ee04-5c1b-a456-be52697a7c10'::uuid, 'Quel démonstratif emploie-t-on pour parler de ce matin ?', 'mcq', '["this morning","that morning","these morning","those morning"]'::jsonb, 0, '« This » vaut aussi pour la proximité dans le temps.', 4),
    ('ecace940-3e56-50dc-abc1-bced3097c176'::uuid, 'eecddf51-ee04-5c1b-a456-be52697a7c10'::uuid, 'Comment se présente-t-on au téléphone en anglais ?', 'mcq', '["This is Paul speaking.","It is Paul speaking.","That is Paul speaking.","Here Paul speaking."]'::jsonb, 0, 'L’anglais emploie le démonstratif là où le français dit « c’est ».', 5),
    ('ef43f68a-306e-5414-927d-66d2aee23599'::uuid, 'eecddf51-ee04-5c1b-a456-be52697a7c10'::uuid, 'Quelle est la différence entre un démonstratif adjectif et pronom ?', 'mcq', '["L’adjectif est suivi d’un nom, le pronom s’emploie seul","L’adjectif est toujours au pluriel","Le pronom se place après le verbe","Il n’y a aucune différence"]'::jsonb, 0, '« This car » contre « This is my car ».', 6),
    ('8725a6a4-d58d-59c9-9e0f-b583253347d7'::uuid, 'eecddf51-ee04-5c1b-a456-be52697a7c10'::uuid, 'Quel démonstratif emploie-t-on pour un souvenir lointain au pluriel ?', 'mcq', '["those","these","that","this"]'::jsonb, 0, '« Those were the days. »', 7),
    ('16873465-e872-5e1a-8ae4-9ecfb9e0044e'::uuid, 'eecddf51-ee04-5c1b-a456-be52697a7c10'::uuid, '« Those » peut s’écrire « thoses » au pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est déjà pluriel : les démonstratifs ne prennent jamais de -s supplémentaire.', 8),
    ('0b910b41-469f-5677-b862-6181ce07274f'::uuid, 'a053af60-8411-57b0-af09-56a9e0767e1c'::uuid, 'Comment traduit-on « la voiture de mon père » ?', 'mcq', '["my father’s car","the car of my father","my father car","the father’s my car"]'::jsonb, 0, 'L’ordre est inverse du français : possesseur + ’s + objet.', 1),
    ('be12b85d-6759-5b87-b8ed-ce18100bdb24'::uuid, 'a053af60-8411-57b0-af09-56a9e0767e1c'::uuid, 'Comment écrit-on « la chambre des filles » ?', 'mcq', '["the girls’ room","the girl’s room","the girls’s room","the room of girls"]'::jsonb, 0, 'Pluriel déjà en -s : l’apostrophe seule suffit.', 2),
    ('1e0d8b88-9a3f-5a77-bd5d-5029c480bc56'::uuid, 'a053af60-8411-57b0-af09-56a9e0767e1c'::uuid, 'Comment écrit-on « les jouets des enfants » ?', 'mcq', '["the children’s toys","the childrens’ toys","the children toys","the toys of children"]'::jsonb, 0, 'Pluriel irrégulier : on ajoute ’s normalement.', 3),
    ('3778976e-d0f6-5924-88b4-6dfaaa5c8a8f'::uuid, 'a053af60-8411-57b0-af09-56a9e0767e1c'::uuid, 'Quel possessif emploie-t-on avec un objet inanimé ?', 'mcq', '["La structure avec « of » : the roof of the house","Toujours ’s","Toujours « its »","Aucun possessif n’est possible"]'::jsonb, 0, 'Le génitif ’s est réservé surtout aux êtres animés et au temps.', 4),
    ('bac6b05d-3fac-5d15-a984-0ac2a59bac75'::uuid, 'a053af60-8411-57b0-af09-56a9e0767e1c'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["This book is mine.","This book is my.","This is mine book.","This book is my one."]'::jsonb, 0, 'Le pronom possessif n’est jamais suivi d’un nom.', 5),
    ('6f31a5fc-a427-58a6-985f-7d49fd57458f'::uuid, 'a053af60-8411-57b0-af09-56a9e0767e1c'::uuid, 'Avec quoi le possessif s’accorde-t-il en anglais ?', 'mcq', '["Avec le possesseur","Avec l’objet possédé","Avec le verbe","Avec le sujet de la phrase"]'::jsonb, 0, '« Paul and his sister », « Kate and her brother ».', 6),
    ('0df49010-e3da-58de-b62b-de1f5bf846da'::uuid, 'a053af60-8411-57b0-af09-56a9e0767e1c'::uuid, 'Quelle est la différence entre « its » et « it’s » ?', 'mcq', '["« its » est le possessif, « it’s » la contraction de « it is »","« its » est la contraction de « it is »","Les deux sont interchangeables","« it’s » est le possessif au pluriel"]'::jsonb, 0, 'L’apostrophe marque la contraction, jamais le possessif de « it ».', 7),
    ('fab9f053-cecb-5732-8329-c38969023281'::uuid, 'a053af60-8411-57b0-af09-56a9e0767e1c'::uuid, 'On dit « the car of my father » pour traduire « la voiture de mon père ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Avec un être animé, l’anglais emploie le génitif : « my father’s car ».', 8),
    ('0491f312-1ee4-56d5-9723-151e3af7766e'::uuid, '43f7ca0a-21e2-5bb8-8252-0a36053b50ce'::uuid, 'Quel quantifieur emploie-t-on dans une phrase négative ?', 'mcq', '["any","some","much of","a few"]'::jsonb, 0, '« I don’t have any money. »', 1),
    ('6b3d38fe-fe93-5f50-af64-1537c7a27cc5'::uuid, '43f7ca0a-21e2-5bb8-8252-0a36053b50ce'::uuid, 'Quel quantifieur emploie-t-on avec un nom indénombrable dans une question ?', 'mcq', '["much","many","a few","several"]'::jsonb, 0, '« How much water? » contre « How many books? »', 2),
    ('8e55cf44-ff25-55e5-a555-dc79f86316a3'::uuid, '43f7ca0a-21e2-5bb8-8252-0a36053b50ce'::uuid, 'Que signifie « a few friends » ?', 'mcq', '["Quelques amis, un nombre suffisant","Trop peu d’amis","Aucun ami","Beaucoup d’amis"]'::jsonb, 0, 'Sans l’article, « few friends » a un sens négatif.', 3),
    ('4ec298e8-a9d1-5bfd-920b-39b24074182e'::uuid, '43f7ca0a-21e2-5bb8-8252-0a36053b50ce'::uuid, 'Quel quantifieur emploie-t-on avec un indénombrable pour dire « un peu de » ?', 'mcq', '["a little","a few","many","several"]'::jsonb, 0, '« A little time », « a few minutes ».', 4),
    ('47116bac-ace2-56be-a710-f740a319e56f'::uuid, '43f7ca0a-21e2-5bb8-8252-0a36053b50ce'::uuid, 'Quelle phrase propose poliment quelque chose ?', 'mcq', '["Would you like some tea?","Would you like any tea?","Do you like some tea?","Would you like much tea?"]'::jsonb, 0, '« Some » s’emploie dans les offres et demandes polies.', 5),
    ('080e2336-213d-51ad-98a9-358121b0a1ae'::uuid, '43f7ca0a-21e2-5bb8-8252-0a36053b50ce'::uuid, 'Que signifie « any » dans une phrase affirmative ?', 'mcq', '["N’importe quel","Aucun","Beaucoup de","Quelques"]'::jsonb, 0, '« Take any book you like. »', 6),
    ('949f48f4-ccbf-57a2-ad87-458c340e9af2'::uuid, '43f7ca0a-21e2-5bb8-8252-0a36053b50ce'::uuid, 'Quel quantifieur remplace « much » et « many » à l’affirmative ?', 'mcq', '["a lot of","any","no","each"]'::jsonb, 0, 'Il fonctionne avec les dénombrables comme avec les indénombrables.', 7),
    ('a2984bc2-d3ad-5a34-a18f-04ac298e703c'::uuid, '43f7ca0a-21e2-5bb8-8252-0a36053b50ce'::uuid, '« Few » et « a few » ont exactement le même sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« A few » signifie « quelques, assez » ; « few » signifie « trop peu ».', 8),
    ('9ecc0288-af82-5077-b504-002e3e830fc1'::uuid, 'e2fb2382-f447-5a34-a8e7-77e1ceed958a'::uuid, 'Où se place l’adjectif en anglais ?', 'mcq', '["Avant le nom","Après le nom","À la fin de la phrase","Cela dépend de son sens"]'::jsonb, 0, '« A beautiful house », l’inverse du français.', 1),
    ('a8e3ab12-aedf-5353-9c5b-45e7249b0445'::uuid, 'e2fb2382-f447-5a34-a8e7-77e1ceed958a'::uuid, 'Comment l’adjectif anglais s’accorde-t-il ?', 'mcq', '["Il est invariable","Il s’accorde en nombre","Il s’accorde en genre","Il s’accorde en genre et en nombre"]'::jsonb, 0, '« Two red cars », sans -s à l’adjectif.', 2),
    ('78d182e9-0f32-5c92-9d01-90af1dd97945'::uuid, 'e2fb2382-f447-5a34-a8e7-77e1ceed958a'::uuid, 'Que signifie « I am bored » ?', 'mcq', '["Je m’ennuie","Je suis ennuyeux","J’ennuie les autres","Je suis fatigant"]'::jsonb, 0, 'La forme en -ed décrit ce que ressent la personne.', 3),
    ('de871a35-bbae-50b3-9846-da667427c1c0'::uuid, 'e2fb2382-f447-5a34-a8e7-77e1ceed958a'::uuid, 'Comment dit-on « le film est ennuyeux » ?', 'mcq', '["The film is boring.","The film is bored.","The film is boredom.","The film is bore."]'::jsonb, 0, 'La forme en -ing décrit ce qui provoque le sentiment.', 4),
    ('877e9b3e-2ae7-5e0a-a2cb-342af42d72c4'::uuid, 'e2fb2382-f447-5a34-a8e7-77e1ceed958a'::uuid, 'Quel est l’ordre correct des adjectifs ?', 'mcq', '["a small old black car","a black old small car","an old black small car","a black small old car"]'::jsonb, 0, 'Taille, puis âge, puis couleur.', 5),
    ('6a30481f-4180-52ff-96b2-cd5239d26b70'::uuid, 'e2fb2382-f447-5a34-a8e7-77e1ceed958a'::uuid, 'Comment écrit-on « un garçon de cinq ans » ?', 'mcq', '["a five-year-old boy","a five-years-old boy","a five year old boy","a boy of five years old"]'::jsonb, 0, 'Adjectif composé : traits d’union et nom au singulier.', 6),
    ('0ab77498-c672-5762-82c3-c6ccea9cbf8a'::uuid, 'e2fb2382-f447-5a34-a8e7-77e1ceed958a'::uuid, 'Après quels verbes l’adjectif peut-il se placer ?', 'mcq', '["Après be, seem, look, feel, become","Après tous les verbes","Après les verbes d’action uniquement","Jamais après un verbe"]'::jsonb, 0, 'Ce sont les verbes d’état : « She looks tired. »', 7),
    ('6368257e-2fee-5c2f-ab86-dbc31d6698c6'::uuid, 'e2fb2382-f447-5a34-a8e7-77e1ceed958a'::uuid, '« The poor » se construit avec un verbe au singulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un adjectif substantivé désigne un groupe : le verbe se met au pluriel.', 8),
    ('8ad0c9d8-e931-5067-b21a-6f7fac027630'::uuid, '5f2fbb3c-1d17-5ead-b96c-bc6c1d60ba72'::uuid, 'À quoi servent les auxiliaires ?', 'mcq', '["À construire la question, la négation et la reprise courte","À donner le sens principal du verbe","À accorder le verbe avec le sujet","À former le pluriel"]'::jsonb, 0, 'Les verbes lexicaux, eux, portent le sens.', 1),
    ('ffd1773d-f65f-5bb5-a1c0-322660a25859'::uuid, '5f2fbb3c-1d17-5ead-b96c-bc6c1d60ba72'::uuid, 'Quel auxiliaire forme les temps en -ING et la voix passive ?', 'mcq', '["be","have","do","will"]'::jsonb, 0, '« She is working », « It was built ».', 2),
    ('43ecbbbd-ba58-52ef-a02c-c97665be7a50'::uuid, '5f2fbb3c-1d17-5ead-b96c-bc6c1d60ba72'::uuid, 'Quel auxiliaire forme les temps composés ?', 'mcq', '["have","be","do","can"]'::jsonb, 0, '« I have finished. »', 3),
    ('b36b65e3-b2ce-5fde-8889-aa067e848295'::uuid, '5f2fbb3c-1d17-5ead-b96c-bc6c1d60ba72'::uuid, 'À quoi sert l’auxiliaire « do » ?', 'mcq', '["À la négation, à l’interrogation et à l’insistance aux temps simples","À former le passif","À former le present perfect","À exprimer la capacité"]'::jsonb, 0, '« I don’t know », « Do you know? »', 4),
    ('091a6f26-99da-57dc-ba2d-844774717f05'::uuid, '5f2fbb3c-1d17-5ead-b96c-bc6c1d60ba72'::uuid, 'Où se place l’auxiliaire dans une question ?', 'mcq', '["Devant le sujet","Après le verbe","À la fin de la phrase","Il disparaît"]'::jsonb, 0, '« Are you ready? », « Have you finished? »', 5),
    ('4052d305-5cfe-59f6-b8a7-23ba1648a536'::uuid, '5f2fbb3c-1d17-5ead-b96c-bc6c1d60ba72'::uuid, 'Où se place « not » dans une négation ?', 'mcq', '["Juste après l’auxiliaire","Avant l’auxiliaire","Après le verbe lexical","À la fin de la phrase"]'::jsonb, 0, 'isn’t, hasn’t, doesn’t, can’t.', 6),
    ('8694bf0c-380b-52f4-90c9-d4bb857f3447'::uuid, '5f2fbb3c-1d17-5ead-b96c-bc6c1d60ba72'::uuid, 'Comment répond-on brièvement à « Do you like tea? » ?', 'mcq', '["Yes, I do.","Yes, I like.","Yes, I am.","Yes, I have."]'::jsonb, 0, 'La reprise courte réutilise l’auxiliaire de la question.', 7),
    ('741d7d51-22e1-5c3f-a05d-ccfa361cb8d8'::uuid, '5f2fbb3c-1d17-5ead-b96c-bc6c1d60ba72'::uuid, '« Have » au sens de posséder se construit sans auxiliaire dans une question.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est alors lexical et demande « do » : « Do you have a car? »', 8),
    ('877d5a48-3aa4-55bd-a4aa-e260ef450508'::uuid, 'bc7fa825-0bcc-5da1-bb35-8f66a740dcdb'::uuid, 'Comment dit-on « J’ai 15 ans » ?', 'mcq', '["I am 15.","I have 15.","I have 15 years.","I am 15 years."]'::jsonb, 0, 'L’anglais emploie « be » là où le français emploie « avoir ».', 1),
    ('261e585b-ace0-5a79-8a96-49b1e3bb5164'::uuid, 'bc7fa825-0bcc-5da1-bb35-8f66a740dcdb'::uuid, 'Quelle est la forme de « be » au prétérit avec « they » ?', 'mcq', '["were","was","been","are"]'::jsonb, 0, 'I, he, she, it prennent « was ».', 2),
    ('cd067f9e-5e1c-5442-959a-e2a6356ebe41'::uuid, 'bc7fa825-0bcc-5da1-bb35-8f66a740dcdb'::uuid, 'Quel est le participe passé de « be » ?', 'mcq', '["been","was","being","be"]'::jsonb, 0, '« I have been to London. »', 3),
    ('2d1fe941-1b7f-53b8-bc92-77bc5c1a367c'::uuid, 'bc7fa825-0bcc-5da1-bb35-8f66a740dcdb'::uuid, 'Quelle est la forme de « have » à la troisième personne du singulier au présent ?', 'mcq', '["has","have","haves","had"]'::jsonb, 0, '« She has a bike. »', 4),
    ('43f7deea-7921-5548-a1c4-d4649a546694'::uuid, 'bc7fa825-0bcc-5da1-bb35-8f66a740dcdb'::uuid, 'Comment interroge-t-on avec « have got » ?', 'mcq', '["Have you got a bike?","Do you have got a bike?","Do you got a bike?","Are you got a bike?"]'::jsonb, 0, '« Have got » se passe de « do » : l’auxiliaire est déjà là.', 5),
    ('aaa13336-cc45-5a4a-bedc-f4743be0699f'::uuid, 'bc7fa825-0bcc-5da1-bb35-8f66a740dcdb'::uuid, 'Quel auxiliaire forme la voix passive ?', 'mcq', '["be","have","do","will"]'::jsonb, 0, '« The window was broken. »', 6),
    ('cac936ee-601e-544c-bd2c-777321d54282'::uuid, 'bc7fa825-0bcc-5da1-bb35-8f66a740dcdb'::uuid, 'Que peut signifier la contraction « he’s » ?', 'mcq', '["« he is » ou « he has »","« he is » uniquement","« he has » uniquement","« he was »"]'::jsonb, 0, 'C’est ce qui suit qui tranche : « he’s tired » ou « he’s finished ».', 7),
    ('09c8f19c-ad32-5e9c-9946-cd1ecfe5b742'::uuid, 'bc7fa825-0bcc-5da1-bb35-8f66a740dcdb'::uuid, '« Have » est toujours un auxiliaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est lexical dans « I have a bike » ou « have breakfast ».', 8),
    ('2512318b-2d0e-5986-81a4-0626c70b7063'::uuid, '6c24c668-7123-58df-984a-231f9ee685d3'::uuid, 'Dans quels cas l’auxiliaire DO apparaît-il ?', 'mcq', '["À la négation, à l’interrogation et à l’insistance","Dans toutes les phrases","Seulement au passé","Seulement avec les modaux"]'::jsonb, 0, 'Aux temps simples uniquement.', 1),
    ('56c3608e-837d-5eaa-b02d-e0e4fe460738'::uuid, '6c24c668-7123-58df-984a-231f9ee685d3'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["She doesn’t work here.","She doesn’t works here.","She don’t works here.","She not work here."]'::jsonb, 0, 'DO porte la marque de la personne, le verbe revient à la base verbale.', 2),
    ('66039f6c-9c4e-562d-a01d-537a9ca99e08'::uuid, '6c24c668-7123-58df-984a-231f9ee685d3'::uuid, 'Comment met-on « He went » à la forme négative ?', 'mcq', '["He didn’t go.","He didn’t went.","He not went.","He doesn’t went."]'::jsonb, 0, 'Une phrase ne porte qu’une seule marque de temps.', 3),
    ('58a056ab-9fb4-57d2-9468-a41d512f9643'::uuid, '6c24c668-7123-58df-984a-231f9ee685d3'::uuid, 'Quelle question est correcte ?', 'mcq', '["Did you go to school?","Did you went to school?","Do you went to school?","You did go to school?"]'::jsonb, 0, 'DID porte le passé, le verbe reste à la base verbale.', 4),
    ('249c4d51-3b74-5b6b-916f-ede843209cf0'::uuid, '6c24c668-7123-58df-984a-231f9ee685d3'::uuid, 'Avec quel verbe l’auxiliaire DO n’apparaît-il jamais ?', 'mcq', '["be","work","go","like"]'::jsonb, 0, '« Be » est son propre auxiliaire : « Is she a teacher? »', 5),
    ('e4ef7ae9-42b1-53fc-a4dc-c93cf1be9dd3'::uuid, '6c24c668-7123-58df-984a-231f9ee685d3'::uuid, 'Que signifie « I do like it » ?', 'mcq', '["J’aime vraiment ça : c’est une insistance","Je fais ce que j’aime","Je n’aime pas ça","C’est une question"]'::jsonb, 0, 'La forme emphatique s’accentue à l’oral.', 6),
    ('37d1cd38-7afb-5e20-a964-2ea4ff8355f7'::uuid, '6c24c668-7123-58df-984a-231f9ee685d3'::uuid, 'Quand « who » est sujet de la question, emploie-t-on DO ?', 'mcq', '["Non : « Who broke the window? »","Oui, toujours","Oui, seulement au passé","Oui, seulement au présent"]'::jsonb, 0, 'Le sujet étant déjà en tête, l’ordre n’a pas à être inversé.', 7),
    ('e72194fe-2c82-533a-8d28-c6c8ad300cfd'::uuid, '6c24c668-7123-58df-984a-231f9ee685d3'::uuid, 'On peut écrire « Did you went? » au passé.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'DID porte déjà le passé : le verbe reste à la base verbale.', 8),
    ('9e69c035-d91f-585d-ada5-fbc77e4e50b8'::uuid, 'aa57bb25-19d9-560d-8f09-5c712e9aaf42'::uuid, 'D’où vient l’obligation exprimée par « must » ?', 'mcq', '["De celui qui parle","Du règlement extérieur","D’une loi écrite","De personne"]'::jsonb, 0, '« Have to » exprime, lui, une contrainte extérieure.', 1),
    ('a5c886bc-595f-540c-a944-d3b185b3eea0'::uuid, 'aa57bb25-19d9-560d-8f09-5c712e9aaf42'::uuid, 'Que signifie « You mustn’t smoke here » ?', 'mcq', '["Il est interdit de fumer ici","Tu n’es pas obligé de fumer","Tu peux fumer si tu veux","Tu devrais fumer dehors"]'::jsonb, 0, '« Mustn’t » exprime l’interdiction.', 2),
    ('74f0a5a5-2018-5347-9a44-1b0d7a473a62'::uuid, 'aa57bb25-19d9-560d-8f09-5c712e9aaf42'::uuid, 'Que signifie « You don’t have to come » ?', 'mcq', '["Tu n’es pas obligé de venir","Il t’est interdit de venir","Tu dois venir","Tu devrais venir"]'::jsonb, 0, 'Absence d’obligation, pas interdiction.', 3),
    ('9014ac29-8cdb-561e-bc6a-c4cbefd5a924'::uuid, 'aa57bb25-19d9-560d-8f09-5c712e9aaf42'::uuid, 'Comment exprime-t-on l’obligation au passé ?', 'mcq', '["had to","musted","must have","was must"]'::jsonb, 0, '« Must » n’a pas de forme passée.', 4),
    ('95f2e4a8-9c73-541d-aa80-556c2107e57a'::uuid, 'aa57bb25-19d9-560d-8f09-5c712e9aaf42'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["She must go now.","She musts go now.","She must to go now.","She must going now."]'::jsonb, 0, 'Un modal est invariable et se construit sans « to ».', 5),
    ('d3a7c2ff-06cb-50cc-93f1-85009af366fd'::uuid, 'aa57bb25-19d9-560d-8f09-5c712e9aaf42'::uuid, 'Comment interroge-t-on avec « have to » ?', 'mcq', '["Do you have to go?","Have you to go?","Do you must go?","Are you have to go?"]'::jsonb, 0, '« Have to » se comporte comme un verbe lexical : il demande « do ».', 6),
    ('0aed8bef-c9b5-5e01-9dc0-30bd6409ef75'::uuid, 'aa57bb25-19d9-560d-8f09-5c712e9aaf42'::uuid, 'Quel modal exprime le conseil plutôt que l’obligation ?', 'mcq', '["should","must","have to","need to"]'::jsonb, 0, '« You should see a doctor. »', 7),
    ('f8a86acf-373d-5718-a54f-ef4d2bc4cbe9'::uuid, 'aa57bb25-19d9-560d-8f09-5c712e9aaf42'::uuid, '« Mustn’t » et « don’t have to » ont le même sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le premier interdit, le second dispense : c’est le piège du chapitre.', 8),
    ('598be22c-d51f-5cb8-bbe9-0d2c5464544d'::uuid, 'eedc53a0-1b3b-5dff-9c83-e191e598a84f'::uuid, 'Quel modal exprime la capacité au présent ?', 'mcq', '["can","must","should","may"]'::jsonb, 0, '« I can swim. »', 1),
    ('53eaa0a3-7e96-559d-b244-0d3dccd68a86'::uuid, 'eedc53a0-1b3b-5dff-9c83-e191e598a84f'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["She can speak three languages.","She cans speak three languages.","She can to speak three languages.","She can speaking three languages."]'::jsonb, 0, 'Un modal est invariable et se construit sans « to ».', 2),
    ('7f98a357-51b8-5f0b-8cc2-bd153edc55c7'::uuid, 'eedc53a0-1b3b-5dff-9c83-e191e598a84f'::uuid, 'Comment exprime-t-on une capacité passée générale ?', 'mcq', '["could","can","was can","could to"]'::jsonb, 0, '« I could swim when I was five. »', 3),
    ('6bb22803-ffbf-536d-ab36-70940e654b2d'::uuid, 'eedc53a0-1b3b-5dff-9c83-e191e598a84f'::uuid, 'Comment exprime-t-on une réussite ponctuelle au passé ?', 'mcq', '["was/were able to","could","can","must have"]'::jsonb, 0, '« He was able to open the door » : il y est parvenu cette fois-là.', 4),
    ('6972a77c-998a-5cb8-94e4-2987eaf65d76'::uuid, 'eedc53a0-1b3b-5dff-9c83-e191e598a84f'::uuid, 'Comment exprime-t-on une capacité future ?', 'mcq', '["will be able to","will can","can will","shall can"]'::jsonb, 0, 'Deux modaux ne peuvent jamais se suivre.', 5),
    ('d2147eb8-e938-5ef0-a7fa-591e0f96bc5b'::uuid, 'eedc53a0-1b3b-5dff-9c83-e191e598a84f'::uuid, 'Comment traduit-on « Je vois la mer d’ici » ?', 'mcq', '["I can see the sea from here.","I see the sea from here, can.","I am seeing the sea from here.","I could see the sea from here."]'::jsonb, 0, 'Avec les verbes de perception, « can » ne se traduit pas en français.', 6),
    ('d2203ed7-c0c4-57d3-9db7-3e76f270d671'::uuid, 'eedc53a0-1b3b-5dff-9c83-e191e598a84f'::uuid, 'Quelle formule est la plus polie pour demander de l’aide ?', 'mcq', '["Could you help me, please?","Can you help me!","You must help me.","You help me?"]'::jsonb, 0, '« Could » atténue la demande.', 7),
    ('26868e30-19d0-549e-bcd1-67ff19edec22'::uuid, 'eedc53a0-1b3b-5dff-9c83-e191e598a84f'::uuid, 'On peut dire « I will can swim » pour exprimer une capacité future.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Deux modaux ne se suivent jamais : « I will be able to swim ».', 8),
    ('701ee106-47c7-5756-8707-5538b8154711'::uuid, 'afe973c9-a6c1-5b25-bdf4-de0f1f00acbf'::uuid, 'Quel modal est le plus formel pour demander la permission ?', 'mcq', '["may","can","could","must"]'::jsonb, 0, '« May I come in? » s’emploie à l’écrit ou avec un adulte.', 1),
    ('c6d1ce0c-73e8-558e-9473-a3d18795a415'::uuid, 'afe973c9-a6c1-5b25-bdf4-de0f1f00acbf'::uuid, 'Quelle phrase demande poliment une permission ?', 'mcq', '["Could I borrow your pen?","You could borrow my pen.","I can borrow your pen.","Must I borrow your pen?"]'::jsonb, 0, '« Could » sert à demander, jamais à accorder.', 2),
    ('0692e267-5c60-5109-90e8-793b96c61597'::uuid, 'afe973c9-a6c1-5b25-bdf4-de0f1f00acbf'::uuid, 'Comment accorde-t-on une permission de façon familière ?', 'mcq', '["You can use my phone.","You could use my phone.","You may not use my phone.","You must use my phone."]'::jsonb, 0, '« Could » n’accorde pas : il suggérerait.', 3),
    ('adb69725-6275-511e-a5cd-3362e8c076a1'::uuid, 'afe973c9-a6c1-5b25-bdf4-de0f1f00acbf'::uuid, 'Comment exprime-t-on une permission au passé ?', 'mcq', '["I was allowed to go.","I could to go.","I may went.","I can went."]'::jsonb, 0, '« Could » ne convient pas pour une permission accordée une fois.', 4),
    ('06491064-6ec1-5b35-bfaf-81fd9bc07a19'::uuid, 'afe973c9-a6c1-5b25-bdf4-de0f1f00acbf'::uuid, 'Que signifie « You mustn’t touch it » ?', 'mcq', '["C’est une interdiction stricte","Tu n’es pas obligé d’y toucher","Tu peux y toucher","Tu devrais y toucher"]'::jsonb, 0, 'Plus fort que « you can’t ».', 5),
    ('5919f44c-72cb-5856-b7fd-c63bf287ae2e'::uuid, 'afe973c9-a6c1-5b25-bdf4-de0f1f00acbf'::uuid, 'Quelle forme se conjugue à tous les temps ?', 'mcq', '["be allowed to","may","can","could"]'::jsonb, 0, '« I will be allowed to vote at 18. »', 6),
    ('5f06aceb-1359-5c88-8dc4-a85a63d06c59'::uuid, 'afe973c9-a6c1-5b25-bdf4-de0f1f00acbf'::uuid, 'Quelle formule apparaît dans un règlement écrit ?', 'mcq', '["Students may not use their phones.","Students can’t use their phones, ok?","Students could not use phones.","Students don’t use phones."]'::jsonb, 0, '« May not » appartient au registre formel.', 7),
    ('689f778b-8104-51be-8261-5f10cac8e1c5'::uuid, 'afe973c9-a6c1-5b25-bdf4-de0f1f00acbf'::uuid, '« Could » sert aussi bien à demander qu’à accorder une permission.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Pour accorder, on emploie « can » ou « may ».', 8),
    ('b617af9d-59d1-5e62-a39d-6922351b4e31'::uuid, 'a7d64ece-af8c-5855-9b27-f4449a4944a8'::uuid, 'Quel modal exprime le conseil de base ?', 'mcq', '["should","must","can","may"]'::jsonb, 0, '« You should revise for the test. »', 1),
    ('56524e18-f772-50ec-82c8-5b179f86f5dc'::uuid, 'a7d64ece-af8c-5855-9b27-f4449a4944a8'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["You should revise tonight.","You should to revise tonight.","You shoulds revise tonight.","You should revising tonight."]'::jsonb, 0, 'Un modal est suivi de la base verbale sans « to ».', 2),
    ('90fa36b0-77d0-5e7c-bd31-970a2b869ce8'::uuid, 'a7d64ece-af8c-5855-9b27-f4449a4944a8'::uuid, 'Quel modal du conseil se construit avec « to » ?', 'mcq', '["ought to","should","must","had better"]'::jsonb, 0, 'C’est le seul modal suivi de « to ».', 3),
    ('4795629a-c1c3-59c6-9b00-69d33b5a770f'::uuid, 'a7d64ece-af8c-5855-9b27-f4449a4944a8'::uuid, 'Que signifie « You’d better hurry » ?', 'mcq', '["Tu ferais mieux de te dépêcher, sinon…","Tu pourrais te dépêcher","Tu es obligé de te dépêcher","Tu as bien fait de te dépêcher"]'::jsonb, 0, 'Un conseil pressant, avec une conséquence implicite.', 4),
    ('3a85be55-5933-5b06-8a43-36dde89efc97'::uuid, 'a7d64ece-af8c-5855-9b27-f4449a4944a8'::uuid, 'Comment se construit « had better » ?', 'mcq', '["had better + base verbale","had better + to + verbe","had better + verbe en -ing","had better + participe passé"]'::jsonb, 0, 'Malgré le « had », il n’y a ni « to » ni passé.', 5),
    ('868878bc-2719-5a9d-b4fc-6834f80ea8e5'::uuid, 'a7d64ece-af8c-5855-9b27-f4449a4944a8'::uuid, 'Comment dit-on « Tu aurais dû me le dire » ?', 'mcq', '["You should have told me.","You should tell me.","You had better tell me.","You must have told me."]'::jsonb, 0, '« Should have + participe passé » exprime le reproche ou le regret.', 6),
    ('07cd4b20-b516-5cb9-aa3b-7b7687d6d8d2'::uuid, 'a7d64ece-af8c-5855-9b27-f4449a4944a8'::uuid, 'Quelle formule propose un conseil sous forme de question ?', 'mcq', '["Why don’t you call her?","You must call her.","You’d better call her.","You ought to call her."]'::jsonb, 0, 'Elle adoucit le conseil en suggestion.', 7),
    ('01fc58b9-81c8-59f1-81c1-ad794fa86a29'::uuid, 'a7d64ece-af8c-5855-9b27-f4449a4944a8'::uuid, '« Had better » se conjugue au passé comme au présent.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une expression figée qui vaut pour le présent et le futur.', 8),
    ('d7bf92c3-286f-520f-9367-c939c9fc1010'::uuid, '539ff805-b709-58a9-b80b-6040fb3fb6a1'::uuid, 'Comment se construit « Let’s » ?', 'mcq', '["Let’s + base verbale","Let’s + to + verbe","Let’s + verbe en -ING","Let’s + participe passé"]'::jsonb, 0, '« Let’s go to the cinema. »', 1),
    ('ad6a882a-de84-5770-817f-5d2c50eb94e7'::uuid, '539ff805-b709-58a9-b80b-6040fb3fb6a1'::uuid, 'Comment se construit « How about » ?', 'mcq', '["How about + nom ou verbe en -ING","How about + base verbale","How about + to + verbe","How about + participe passé"]'::jsonb, 0, '« How about going out tonight? »', 2),
    ('18096e02-fb10-5eb1-bd83-f35acdd40a94'::uuid, '539ff805-b709-58a9-b80b-6040fb3fb6a1'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["Why don’t we meet at six?","Why don’t we meeting at six?","Why we don’t meet at six?","Why don’t we to meet at six?"]'::jsonb, 0, '« Why don’t we » est suivi de la base verbale.', 3),
    ('9927d27d-7775-585d-a6d0-55c3ccf33e03'::uuid, '539ff805-b709-58a9-b80b-6040fb3fb6a1'::uuid, 'Que signifie « Shall we start? » ?', 'mcq', '["On commence ? — une proposition","Nous commencerons","Nous devons commencer","Nous avons commencé"]'::jsonb, 0, '« Shall » sert à proposer, surtout en anglais britannique.', 4),
    ('2161b09f-9d76-58d5-9e19-4e01efa2aa06'::uuid, '539ff805-b709-58a9-b80b-6040fb3fb6a1'::uuid, 'Comment forme-t-on la négation de « Let’s » ?', 'mcq', '["Let’s not waste time.","Let’s don’t waste time.","Don’t let’s waste time.","Let’s no waste time."]'::jsonb, 0, '« Not » se place directement après « let’s ».', 5),
    ('0a4031d2-ea53-5c40-89b9-fe6f876d8848'::uuid, '539ff805-b709-58a9-b80b-6040fb3fb6a1'::uuid, 'Comment exprime-t-on une préférence ?', 'mcq', '["I’d rather stay home.","I’d rather to stay home.","I’d rather staying home.","I rather would stay home."]'::jsonb, 0, '« Would rather » est suivi de la base verbale.', 6),
    ('dcb8fdb6-1ff5-54b3-984d-f38237044776'::uuid, '539ff805-b709-58a9-b80b-6040fb3fb6a1'::uuid, 'Comment refuse-t-on poliment une suggestion ?', 'mcq', '["I’d rather not.","No.","I don’t want.","Never."]'::jsonb, 0, '« I’m afraid I can’t » convient également.', 7),
    ('68f94556-3e4b-58cc-bad6-28eba7fd7532'::uuid, '539ff805-b709-58a9-b80b-6040fb3fb6a1'::uuid, 'On peut dire « How about go out tonight? ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« How about » exige un nom ou un verbe en -ING : « How about going out? »', 8),
    ('628b6b8d-5513-52fd-a2cc-1c0d7be0f30b'::uuid, '613cdf4b-7b07-5db6-bcb8-cfbadc1a44ae'::uuid, 'Quelle construction suit « would like » ?', 'mcq', '["to + verbe","la base verbale","le verbe en -ING","le participe passé"]'::jsonb, 0, '« I’d like to travel. »', 1),
    ('0aeb401b-e645-557b-a956-cbab7c15822e'::uuid, '613cdf4b-7b07-5db6-bcb8-cfbadc1a44ae'::uuid, 'Quel temps suit « wish » pour un regret sur le présent ?', 'mcq', '["Le prétérit","Le présent","Le past perfect","Le futur"]'::jsonb, 0, '« I wish I had more time. »', 2),
