    ('cd7cc81b-1df9-5092-81de-e1c14f6238e6'::uuid, '613cdf4b-7b07-5db6-bcb8-cfbadc1a44ae'::uuid, 'Comment exprime-t-on le souhait qu’une situation change ?', 'mcq', '["wish + would","wish + will","wish + can","wish + must"]'::jsonb, 0, '« I wish it would stop raining. »', 4),
