    ('999e00fa-e48e-5c41-aaaa-54f0c10e85fe'::uuid, '74b8f34e-0517-585c-a65f-d052336b4543'::uuid, 'Quelle forme suit « be used to » ?', 'mcq', '["Le verbe en -ING ou un nom","La base verbale","Le participe passé","Le prétérit"]'::jsonb, 0, '« I am used to getting up early. »', 4),
