    ('df47ab6c-a959-593c-9551-a579f0e56746'::uuid, '74b8f34e-0517-585c-a65f-d052336b4543'::uuid, 'Quand peut-on employer « would » pour une habitude passée ?', 'mcq', '["Pour des actions répétées, jamais pour un état","Pour tous les cas","Uniquement pour les états","Uniquement au négatif"]'::jsonb, 0, '« I would be shy » est faux : il faut « I used to be shy ».', 7),
