    ('83f89882-c4a1-557b-a5a1-30dfbb737530'::uuid, '3d52d6fc-5988-567a-95d8-cccac52ee0aa'::uuid, 'Dans quel cas emploie-t-on « for » ?', 'mcq', '["Devant un nom, ou devant -ING pour dire à quoi sert un objet","Devant une base verbale","Devant un participe passé","Jamais"]'::jsonb, 0, '« This knife is for cutting bread. »', 6),
