    ('515dfbdf-9771-5731-a8e5-12d9019e3caf'::uuid, '55746a39-87aa-58b5-9a76-d1f288edd2bc'::uuid, 'Avec quel temps s’emploie « since » ?', 'mcq', '["Le present perfect","Le prétérit","Le futur","Le présent simple"]'::jsonb, 0, 'Il relie un point du passé au présent.', 5),
