    ('95759f5a-2e60-5ab5-a266-d142018b431f'::uuid, 'e9ddb514-2edc-5d9d-bd25-23798d1e1f50'::uuid, 'Quel est l’ordre des mots dans une question rapportée ?', 'mcq', '["Celui de l’affirmative","Celui de l’interrogative, avec inversion","Le verbe en premier","Le complément en premier"]'::jsonb, 0, '« He asked me where I lived », pas « where did I live ».', 6),
