    ('f47cbc86-b620-5dae-be54-b0659d4bb9fe'::uuid, 'e9ddb514-2edc-5d9d-bd25-23798d1e1f50'::uuid, 'Le recul des temps s’applique même quand le verbe introducteur est au présent.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« He says he is tired » garde le présent.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('anglais');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('anglais')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 298 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 298 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
